def annotate_catalog_reachability(
    methods: Mapping[str, SelectionCandidate],
    target_domain_ids: tuple[str, ...],
) -> tuple[dict[str, SelectionCandidate], list[str]]:
    """5ms deterministic reverse-hypergraph reachability over semantic domain_ids."""
    if not target_domain_ids:
        return dict(methods), list(methods.keys())[:12]
    targets = [{"domain_id": d} for d in target_domain_ids]
    direct: set[str] = set()
    needed_upstream: list[dict[str, str]] = []
    for alias, cand in methods.items():
        if any(
            slot_meaning_compatible(slot.meaning, t)
            for slot in cand.outputs.values()
            for t in targets
        ):
            direct.add(alias)
            for in_slot in cand.inputs.values():
                if "domain_id" in in_slot.meaning:
                    needed_upstream.append(dict(in_slot.meaning))
    upstream: set[str] = set()
    if needed_upstream:
        for alias, cand in methods.items():
            if alias in direct:
                continue
            if any(
                slot_meaning_compatible(slot.meaning, req)
                for slot in cand.outputs.values()
                for req in needed_upstream
            ):
                upstream.add(alias)
    annotated: dict[str, SelectionCandidate] = {}
    ranked: list[str] = []
    for alias, cand in methods.items():
        tag: Literal["direct_deliverable", "upstream_producer", "available"] = (
            "direct_deliverable"
            if alias in direct
            else ("upstream_producer" if alias in upstream else "available")
        )
        annotated[alias] = cand.model_copy(update={"reachability": tag})
    for group in (direct, upstream):
        for alias in methods:
            if alias in group and alias not in ranked:
                ranked.append(alias)
    for alias in methods:
        if alias not in ranked:
            ranked.append(alias)
    return annotated, ranked[:12]


def required_features(selection: Selection) -> set[str]:
    features = {"object_batch"} if selection.object_batch else set()
    for step in selection.steps:
        if step.step_batch is not None:
            features.add("object_batch")
        deps: set[str] = set()
        for b in step.inputs.values():
            if b.source == "step":
                deps.add(b.step)
            elif b.source == "collect_pack":
                deps.update(m.step for m in b.items)
        if step.cases or step.artifact_guard is not None:
            features.add("conditional")
        if step.reviews:
            features.add("independent_review")
        if len(deps) > 1:
            features.add("join")
        elif deps:
            features.add("sequence")
    return features


def routing_alternatives(selection: Selection, methods: dict) -> list[str]:
    if selection.status != "ready" or any(s.cases for s in selection.steps):
        return []

    def input_contract(method):
        return {
            name: {k: slot[k] for k in ("schema", "meaning", "required", "on_missing")}
            for name, slot in method["inputs"].items()
        }

    selected = {step.method for step in selection.steps}
    contracts = [input_contract(methods[a]) for a in selected if a in methods]
    return list(
        dict.fromkeys(
            method["declaration"]["title"]
            for alias, method in methods.items()
            if alias not in selected and input_contract(method) in contracts
        )
    )[:3]


def review_issue(selection: Selection, enabled: dict[str, bool]) -> str | None:
    if selection.status != "ready":
        return None
    features = required_features(selection)
    has_caller_routes = any(bool(s.cases or s.route_input) for s in selection.steps)
    if selection.routing_required != has_caller_routes:
        return "selection_route"
    # Root legacy object_batch still requires at least worker + collector;
    # composable multi-step graphs may freely combine sequence, join, branch,
    # step_batch and independent_review!
    if selection.object_batch is not None and len(selection.steps) < 2:
        return "selection_capability"
    step_ids = {s.id for s in selection.steps}
    for step in selection.steps:
        if step.cases or step.route_input:
            binding = step.inputs.get(step.route_input) if step.route_input else None
            if len(step.cases) < 2 or binding is None or binding.source != "caller":
                return "selection_route"
        if step.reviews:
            deps = {b.step for b in step.inputs.values() if b.source == "step"}
            if (
                not set(step.reviews).issubset(deps)
                or not set(step.reviews).issubset(step_ids)
                or len(step.reviews) not in (1, 2)
                or step.id in step.reviews
            ):
                return "selection_review"
    legacy_claims = {
        "P3": "independent_review",
        "P4": "object_batch",
        "P5": "conditional",
    }
    if any(
        legacy_claims[p] not in features
        for p in selection.patterns or ()
        if p in legacy_claims
    ):
        return "selection_patterns"
    if any(not enabled.get(feature) for feature in features):
        return "selection_capability"
    return None


def normalize_unresolved(value):
    if isinstance(value, dict) and value.get("status") in ("gap", "clarify"):
        return {
            **value,
            "steps": [],
            **({"patterns": []} if "patterns" in value else {}),
            "object_batch": None,
        }
    return value


def check_proposal(selection, methods, instructions, enabled):
    """Check the model's draft against the catalog sealed into this round."""
    if issue := review_issue(selection, enabled):
        advice = {
            "selection_route": "check routing_required, caller input and case labels",
            "selection_capability": "check capabilities and review or batch limits",
            "selection_review": "bind reviewed outputs and list their steps in reviews",
            "selection_patterns": "bind the requested review, batch or routes",
        }
        raise ValueError(f"{issue}: {advice[issue]}")
    seen = {}
    for step in selection.steps:
        candidates = set(step.cases.values()) or {step.method}
        if step.method not in candidates or len(candidates) < len(step.cases):
            raise ValueError(
                f"{step.id}: use distinct route candidates including the named method"
            )
        if candidates & instructions.keys():
            if not (
                len(selection.steps) == 1
                and step.method in instructions
                and not (
                    step.inputs
                    or step.reviews
                    or step.route_input
                    or step.cases
                    or selection.patterns
                    or selection.object_batch
                )
            ):
                raise ValueError(
                    f"{step.id}: an instruction source can only be used alone"
                )
        elif missing := candidates - methods.keys():
            raise ValueError(
                f"{step.id}: method outside the authorized catalog: {sorted(missing)}"
            )
        dependencies: set[str] = set()
        for binding in step.inputs.values():
            if binding.source in ("step", "object_rows"):
                dependencies.add(binding.step)
            elif binding.source == "collect_pack":
                dependencies.update(m.step for m in binding.items)
        if step.artifact_guard is not None:
            dependencies.add(step.artifact_guard.step)
        if step.id in seen or not dependencies <= seen.keys():
            raise ValueError(
                f"{step.id}: use distinct step IDs and bind only earlier results"
            )
        if step.reviews and not methods[step.method].get("isolated_instruction"):
            raise ValueError(
                f"{step.id}: independent reviewer needs an isolated instruction method"
            )
        seen[step.id] = step.method


def _clean_caller_alias(
    raw_name: str, slot_doc: dict[str, Any], chosen_slots: dict[str, dict[str, Any]]
) -> str:
    """Strip internal HTN node prefixes (n1_2_period -> period) when unambiguous."""
    match = NODE_PREFIX_RE.fullmatch(raw_name)
    if not match:
        chosen_slots.setdefault(raw_name, slot_doc)
        return raw_name
    clean = match.group(1)
    if clean not in chosen_slots or chosen_slots[clean] == slot_doc:
        chosen_slots[clean] = slot_doc
        return clean
    chosen_slots.setdefault(raw_name, slot_doc)
    return raw_name


def expand(
    selection: Selection,
    tools: dict[str, FrozenMethod],
    template: DeliveryCriteria | None,
    enabled: dict[str, bool],
    *,
    required_cases: dict[str, set[str]],
    title: str | None = None,
    scope: tuple[str, str] | None = None,
    draft_contract: MethodDraftV2 | None = None,
    step_exports: Mapping[str, tuple[str, str]] | None = None,
    clean_caller_names: bool = False,
):
    if selection.status != "ready":
        raise ValueError("selection_unresolved")
    graph_steps = []
    roles: dict[str, Any] = {}
    permissions: dict[str, Any] = {}
    approvals = []
    issue = review_issue(selection, enabled)
    if issue:
        raise ValueError(issue)
    dependencies: dict[str, set[str]] = {}
    route_values: dict[str, set[str]] = {}
    caller_slots_seen: dict[str, dict[str, Any]] = {}
    should_clean_names = clean_caller_names or draft_contract is not None

    for step in selection.steps:
        aliases = list(step.cases.values()) if step.cases else [step.method]
        if (
            step.method not in aliases
            or any(a not in tools for a in aliases)
            or len(aliases) != len(set(aliases))
        ):
            raise ValueError("selection_candidate")
        chosen = tools[step.method].definition
        interface = chosen.interfaces()
        inputs = {}
        deps = set()
        if step.artifact_guard is not None:
            deps.add(step.artifact_guard.step)
        for name, item in interface["inputs"].items():
            binding = step.inputs.get(name)
            if binding is None:
                if item["required_by"]:
                    raise ValueError("selection_input")
                continue
            if binding.source == "resource":
                raise ValueError("selection_input")
            if binding.source == "literal":
                slot_obj = ValueSlot.model_validate(item["slot"])
                if not slot_obj.accepts(binding.value):
                    raise ValueError("selection_input")
            elif (
                binding.source == "caller"
                and should_clean_names
                and isinstance(binding, CallerValue)
            ):
                cleaned = _clean_caller_alias(
                    binding.name, item["slot"], caller_slots_seen
                )
                if cleaned != binding.name:
                    binding = binding.model_copy(update={"name": cleaned})
            if binding.source in ("step", "object_rows"):
                deps.add(binding.step)
            elif binding.source == "collect_pack":
                deps.update(m.step for m in binding.items)
            inputs[name] = dict(
                slot=item["slot"], binding=binding.model_dump(mode="json")
            )
        if step.inputs.keys() - inputs.keys() or step.id in dependencies:
            raise ValueError("selection_input")
        dependencies[step.id] = deps
        always_req = step.artifact_guard is None
        graph_step: dict[str, Any] = dict(
            id=step.id,
            candidates=[tools[a].reference.model_dump(mode="json") for a in aliases],
            inputs=inputs,
            depends_on=sorted(deps),
            outputs={n: v["slot"] for n, v in interface["outputs"].items()},
            always_required=always_req,
            required_when="when_guard_matched" if not always_req else "always",
            select_when="when_guard_matched" if not always_req else "always",
            on_failure="fail",
        )
        if step.artifact_guard is not None:
            graph_step["artifact_guard"] = step.artifact_guard.model_dump(mode="json")
        if step.step_batch is not None:
            graph_step["step_batch"] = step.step_batch.model_dump(mode="json")
        if step.cases or step.route_input:
            if not step.route_input or len(step.cases) < 2:
                raise ValueError("selection_route")
            route_values[step.id] = set(step.cases)
            graph_step["candidate_choice"] = dict(
                input=step.route_input,
                cases=[
                    dict(
                        equals=label,
                        candidate=tools[a].reference.model_dump(mode="json"),
                    )
                    for label, a in step.cases.items()
                ],
            )
        if step.reviews:
            reviewer_worker = tools.get(step.method)
            if (
                not reviewer_worker
                or reviewer_worker.definition.procedure.kind != "direct"
                or reviewer_worker.definition.procedure.implementation.kind
                not in ("registered_instruction", "skill_instruction")
            ):
                raise ValueError("selection_capability")
            reviewed_set = set(step.reviews)
            if (
                len(reviewed_set) not in (1, 2)
                or not reviewed_set.issubset(deps)
                or step.id in reviewed_set
            ):
                raise ValueError("selection_review")
            for dep in reviewed_set:
                roles.setdefault(dep, dict(isolation_group=dep))
            roles[step.id] = dict(
                isolation_group=step.id,
                handoff_from=sorted(reviewed_set),
                review_requirements={dep: "isolated_reviewer" for dep in reviewed_set},
            )
        for alias in aliases:
            child = tools[alias].definition
            req_id_map: dict[str, str] = {}
            for req in child.access_requirements:
                target_id = req.requirement_id
                effective_req = (
                    req.model_copy(update={"required_when": "when_selected"})
                    if not always_req and req.required_when == "always"
                    else req
                )
                if target_id in permissions and permissions[target_id] != effective_req:
                    # Step-scoped namespacing prevents ID collisions (R03).
                    target_id = f"{step.id}__{req.requirement_id}"[:64]
                    effective_req = effective_req.model_copy(
                        update={
                            "requirement_id": target_id,
                            "origin_steps": (step.id,),
                        }
                    )
                permissions[target_id] = effective_req
                req_id_map[req.requirement_id] = target_id
            for rule in child.what_requires_approval:
                mapped_id = req_id_map.get(rule.requirement_id, rule.requirement_id)
                mapped_rule = (
                    rule.model_copy(update={"requirement_id": mapped_id})
                    if mapped_id != rule.requirement_id
                    else rule
                )
                if mapped_rule not in approvals:
                    approvals.append(mapped_rule)
        graph_steps.append(graph_step)

    if (
        selection.routing_required != bool(route_values)
        or required_cases != route_values
    ):
        raise ValueError("selection_route")

    steps_by_id = {g["id"]: g for g in graph_steps}
    tail = selection.steps[-1]
    if step_exports:
        exports = {
            export_name: dict(
                step=src_step,
                output=src_out,
                always_present=bool(
                    steps_by_id[src_step]["always_required"]
                    and steps_by_id[src_step]["outputs"][src_out]["required"]
                ),
            )
            for export_name, (src_step, src_out) in step_exports.items()
        }
        needed = {src_step for src_step, _ in step_exports.values()}
    else:
        final_def = tools[tail.method].definition
        exports = {
            n: dict(
                step=tail.id,
                output=n,
                always_present=bool(
                    steps_by_id[tail.id]["always_required"] and i["always_present"]
                ),
            )
            for n, i in final_def.interfaces()["outputs"].items()
        }
        needed = {tail.id}

    for s in reversed(selection.steps):
        if s.id in needed:
            needed.update(dependencies[s.id])
    if any(s.id not in needed for s in selection.steps):
        raise ValueError("selection_disconnected")

    procedure: dict[str, Any] = dict(
        kind="orchestration",
        instructions="\n".join(step.task for step in selection.steps),
        steps=graph_steps,
        exports=exports,
        max_depth=16,
        max_steps=100,
        max_expansions=1000,
        max_replans=0,
    )
    if selection.object_batch:
        procedure["object_batch"] = selection.object_batch.model_dump()

    if draft_contract is not None:
        # Whole governs Part: root Elements 1 & 4 come strictly from author-confirmed
        # MethodDraftV2, never cloned from the tail child tool (resolves M02).
        merged_permissions = {
            r.requirement_id: r for r in draft_contract.access_ceiling
        }
        merged_permissions.update(permissions)
        merged_approvals = list(draft_contract.approval_rules)
        for rule in approvals:
            if rule not in merged_approvals:
                merged_approvals.append(rule)
        promises = {
            d.promise_id: d.summary for d in draft_contract.expected_deliverables
        }
        conditions = {
            d.promise_id: PromiseCondition(
                when=d.condition_description or "按条件交付",
                input_slots=(d.condition_input_hint,) if d.condition_input_hint else (),
            ).model_dump(mode="json")
            for d in draft_contract.expected_deliverables
            if d.delivery_mode == "conditional"
        }
        doc: dict[str, Any] = {
            "contract": "knowlab/formal-method/v1",
            "capability_declaration": {
                "title": title or draft_contract.title,
                "purpose": draft_contract.purpose,
                "applies_when": list(draft_contract.applies_when),
                "excludes": list(draft_contract.excludes),
                "promises": promises,
                **({"conditions": conditions} if conditions else {}),
            },
            "access_requirements": [
                r.model_dump(mode="json") for r in merged_permissions.values()
            ],
            "procedure": procedure,
            "how_to_validate": [
                r.model_dump(mode="json") for r in draft_contract.validation_rules
            ],
            "what_requires_approval": [
                r.model_dump(mode="json") for r in merged_approvals
            ],
        }
    else:
        final = tools[tail.method].definition
        doc = final.document()
        doc.update(
            access_requirements=[
                r.model_dump(mode="json") for r in permissions.values()
            ],
            what_requires_approval=[r.model_dump(mode="json") for r in approvals],
            procedure=procedure,
        )
        if template:
            declaration = doc["capability_declaration"]
            if selection.tree and len(selection.steps) > 1:
                applies, excludes = scope or ("", "")
                declaration.update(
                    applies_when=[applies or template.goal],
                    excludes=[excludes] if excludes else [],
                    promises={},
                    conditions={},
                )
                doc["how_to_validate"] = []
            declaration.update(
                title=title or declaration["title"],
                purpose=template.goal,
                promises={
                    **declaration["promises"],
                    "template_delivery": template.deliverable,
                },
            )
            if declaration.get("conditions"):
                declaration["conditions"].pop("template_delivery", None)
            doc["how_to_validate"] = [
                *(
                    v
                    for v in doc["how_to_validate"]
                    if v["promise_id"] != "template_delivery"
                ),
                dict(
                    promise_id="template_delivery",
                    outputs=list(exports),
                    check=template.check,
                    evidence=template.evidence,
                    on_failure="fail",
                ),
            ]

    definition = FormalMethodDefinition.model_validate(doc)
    if roles and isinstance(definition.procedure, Orchestration):
        definition.procedure.validate_collaboration(roles_typed(roles))
        if not review_group(
            definition.procedure.model_copy(
                update={"collaboration": roles_typed(roles)}
            )
        ):
            raise ValueError("selection_capability")
    return FormalMethodDraft(
        definition=definition, source=None, allowed_callers=("host",)
    ), roles or None


def roles_typed(roles):
    from app.domain.workbench.formal_method_generated import CollaborationStep

    return {k: CollaborationStep.model_validate(v) for k, v in roles.items()}


def available(definition, runtime):
    procedure = definition.procedure
    if procedure.kind == "direct":
        kind = procedure.implementation.kind
        if kind not in (
            "mcp",
            "a2a",
            "registered_script",
            "skill_script",
            "skill_instruction",
            "registered_instruction",
            "service_function",
        ):
            return False
        if kind in ("registered_script", "skill_script"):
            return runtime.get("script") is True
        if kind == "service_function":
            return runtime.get("material_read") is True
    else:
        flags = runtime["patterns"]
        if (
            procedure.collaboration
            and not flags.get("independent_review")
            or (procedure.object_batch or procedure.has_step_batch)
            and not flags.get("object_batch")
            or (procedure.has_candidate_choice or procedure.has_artifact_guard)
            and not flags.get("conditional")
        ):
            return False
    return True


def conditional_witnesses(graph, leaf_counts):
    """Cover every candidate and the heaviest route without a Cartesian product."""
    weights: dict[str, dict[str, int]] = {}
    for step in graph.steps:
        choice = step.candidate_choice
        if choice is None:
            continue
        name = step.inputs[choice.input].binding.name
        labels = {case.equals for case in choice.cases}
        totals = weights.setdefault(name, dict.fromkeys(sorted(labels), 0))
        if labels != totals.keys():
            raise ValueError("selection_route")
        for case in choice.cases:
            totals[case.equals] += leaf_counts.get(case.candidate, 1)
    worst = {
        name: max(totals, key=totals.__getitem__) for name, totals in weights.items()
    }
    yield worst
    for name, totals in weights.items():
        for label in totals:
            if label != worst[name]:
                yield {**worst, name: label}


def verify_selection_graph(target, definition, resolved, capabilities, roles=None):
    if any(
        not available(child.definition, capabilities) for child in resolved.values()
    ):
        raise ValueError("selection_capability")
    if roles and isinstance(definition.procedure, Orchestration):
        definition = definition.model_copy(
            update={
                "procedure": definition.procedure.model_copy(
                    update={"collaboration": roles_typed(roles)}
                )
            }
        )
    graph = definition.procedure
    compile_method(target, definition, resolved)
    if graph.kind == "orchestration":
        leaf_counts = {}
        has_dynamic_child = False
        for child in resolved.values():
            nested = child.definition.procedure
            if nested.kind == "orchestration":
                if (
                    nested.collaboration
                    or nested.object_batch
                    or nested.has_step_batch
                    or nested.has_candidate_choice
                    or nested.has_artifact_guard
                ):
                    has_dynamic_child = True
                    _, _, child_leaves = verify_envelope_graph(
                        child.reference.method_id, child.definition, resolved
                    )
                    leaf_counts[child.reference] = child_leaves
                else:
                    nested_plan = expand_unique_plan(
                        child.reference.method_id, child.definition, resolved
                    )
                    leaf_counts[child.reference] = len(nested_plan.leaf_nodes)
            else:
                # Validate direct leaves against fixed leaf execution rules too.
                verify_envelope_graph(
                    child.reference.method_id, child.definition, resolved
                )
        if (
            has_dynamic_child
            or graph.has_artifact_guard
            or graph.has_step_batch
            or (
                graph.has_candidate_choice
                and (graph.collaboration or graph.object_batch)
            )
        ):
            verify_envelope_graph(target, definition, resolved)
            if graph.has_candidate_choice:
                for values in conditional_witnesses(graph, leaf_counts):
                    selected = select_plan(definition, values)
                    verify_envelope_graph(target, selected, resolved)
        elif graph.has_candidate_choice:
            for values in conditional_witnesses(graph, leaf_counts):
                expand_unique_plan(target, select_plan(definition, values), resolved)
        else:
            values = {}
            if graph.object_batch:
                keys = [str(i) for i in range(graph.object_batch.max_objects)]
                values = {
                    port.binding.name: keys
                    for step in graph.steps
                    for port in step.inputs.values()
                    if port.binding.source == "object_item"
                }
            expand_unique_plan(target, select_plan(definition, values), resolved)
